-- State transitions declared for SessionLimit: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION sapiens.session_limits_enforce_limit_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."enforce_limit" IS DISTINCT FROM OLD."enforce_limit" AND NOT (
           (COALESCE(OLD."enforce_limit"::text, ''), COALESCE(NEW."enforce_limit"::text, '')) IN (('false', 'true'), ('true', 'false'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: session_limits.enforce_limit % -> %', OLD."enforce_limit", NEW."enforce_limit"
            USING ERRCODE = 'check_violation', COLUMN = 'enforce_limit', CONSTRAINT = 'tg_session_limits__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS session_limits_enforce_limit_transition_check ON sapiens.session_limits;
CREATE TRIGGER session_limits_enforce_limit_transition_check
    BEFORE UPDATE OF "enforce_limit" ON sapiens.session_limits
    FOR EACH ROW EXECUTE FUNCTION sapiens.session_limits_enforce_limit_transition_check();
